#!/usr/bin/env bash
# Regenerates the Rust code generated by rustorb-idl -brust that is checked
# in: the mapping tests (tests/mapping, CORBA and DDS), the CosNaming stubs
# of rustorb-naming and the stubs of the rustorb interop client and server.
# Needs the pinned rustorb-idl importable (pip install -r
# tools/rustorb-idl.txt, or RUSTORB_IDL_DIR set to a rustorb-idl checkout)
# and rustfmt. CI checks that the committed code is up to date (it runs this
# and git diff).
set -euo pipefail

here="$(cd "$(dirname "$0")" && pwd)"
root="$(cd "$here/.." && pwd)"
mapping="$root/tests/mapping"
pythonpath="${RUSTORB_IDL_DIR:+$RUSTORB_IDL_DIR/python}"
[ -n "${IDL_PARSER_DIR:-}" ] && pythonpath="$IDL_PARSER_DIR${pythonpath:+:$pythonpath}"
idl() {
  PYTHONPATH="$pythonpath${PYTHONPATH:+${pythonpath:+:}$PYTHONPATH}" python3 -m rustorb_idl -brust "$@"
}

idl -C "$mapping/generated" "$mapping/idl/RustMapping.idl"
idl -Wbdds_only -C "$mapping/generated" "$mapping/idl/DdsMapping.idl"
idl -Wbdds -C "$mapping/generated" "$mapping/idl/DdsCorba.idl"
idl -C "$root/crates/rustorb-naming/src/idl" "$mapping/idl/CosNaming.idl"
for f in InteropTest AnyTest ValueTest PoaProbe AbstractTest; do
  idl -I "$root/interop/idl" -C "$root/interop/impls/rustorb/src/idl" "$root/interop/idl/$f.idl"
done
idl -I "$root/interop/idl" -C "$root/interop/impls/rustorb/src/idl" \
  -Wbextern=AnyTest=crate::idl::any_test "$root/interop/idl/AnyTestHidden.idl"
idl -I "$root/interop/idl" -C "$root/interop/impls/rustorb/src/idl" \
  -Wbextern=ValueTest=crate::idl::value_test "$root/interop/idl/CustomTest.idl"
